// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.feedbackimport com.roshan.persona.brain.trace.BrainTraceimport com.roshan.persona.common.CorrelationIdimport timber.log.Timberimport java.time.Instantimport java.util.concurrent.ConcurrentLinkedQueueimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Feedback Collector. * * Collects user feedback (implicit + explicit) for brain requests. Used to: *   - Improve intent classifier (L0) over time *   - Identify bad responses for review *   - Track user satisfaction trends * * ## Feedback Types * *   1. **Explicit** — user taps thumbs up/down on a response *   2. **Implicit positive** — user says "thank you", "perfect", "that's right" *   3. **Implicit negative** — user immediately rephrases, says "no", "wrong" *   4. **Correction** — user provides the correct answer after a failure * * ## Privacy * *   - Feedback stored ON-DEVICE only, never synced to cloud *   - User can view + delete in Settings → Privacy → Feedback *   - Auto-expire after 90 days *   - Used for on-device model fine-tuning (future module) * * @see <a href="docs/spec/module2-spec-review.pdf">§10.5 FeedbackCollector</a> */@Singletonclass FeedbackCollector @Inject constructor(    private val maxEntries: Int = 10_000,) {    private val entries = ConcurrentLinkedQueue<FeedbackEntry>()    /**     * Record explicit feedback (thumbs up/down).     *     * @param correlationId which request this feedback is for     * @param rating positive (thumbs up) or negative (thumbs down)     * @param comment optional user comment     */    fun recordExplicit(        correlationId: CorrelationId,        rating: FeedbackRating,        comment: String? = null,    ) {        val entry = FeedbackEntry(            correlationId = correlationId,            type = FeedbackType.EXPLICIT,            rating = rating,            comment = comment,            timestamp = Instant.now(),        )        addEntry(entry)        Timber.tag("NOUS.Feedback").i("Explicit feedback: %s for %s", rating, correlationId.value.take(8))    }    /**     * Detect and record implicit feedback from the user's next message.     *     * Called by the brain orchestrator when processing a new request — checks     * if the user's input is a positive/negative reaction to the previous response.     *     * @param previousCorrelationId the previous request's correlation ID     * @param userInput the user's current input     * @return true if implicit feedback was detected and recorded     */    fun detectImplicit(        previousCorrelationId: CorrelationId,        userInput: String,    ): Boolean {        val lower = userInput.lowercase().trim()        // Positive patterns        for (pattern in POSITIVE_PATTERNS) {            if (pattern.containsMatchIn(lower)) {                recordImplicit(previousCorrelationId, FeedbackRating.POSITIVE, "Detected: ${pattern.pattern}")                return true            }        }        // Negative patterns        for (pattern in NEGATIVE_PATTERNS) {            if (pattern.containsMatchIn(lower)) {                recordImplicit(previousCorrelationId, FeedbackRating.NEGATIVE, "Detected: ${pattern.pattern}")                return true            }        }        return false    }    /**     * Record a correction (user provides the right answer after a failure).     *     * @param correlationId the failed request     * @param correctAnswer what the user says is correct     */    fun recordCorrection(        correlationId: CorrelationId,        correctAnswer: String,    ) {        val entry = FeedbackEntry(            correlationId = correlationId,            type = FeedbackType.CORRECTION,            rating = FeedbackRating.NEGATIVE,            comment = correctAnswer,            timestamp = Instant.now(),        )        addEntry(entry)        Timber.tag("NOUS.Feedback").i("Correction recorded for %s", correlationId.value.take(8))    }    /**     * Get all feedback entries (for Settings → Privacy → Feedback).     */    fun getAll(): List<FeedbackEntry> = entries.toList().sortedByDescending { it.timestamp }    /**     * Get feedback for a specific request.     */    fun getForRequest(correlationId: CorrelationId): List<FeedbackEntry> =        entries.filter { it.correlationId == correlationId }    /**     * Get aggregate stats (for analytics dashboard).     */    fun getStats(): FeedbackStats {        val total = entries.size        val positive = entries.count { it.rating == FeedbackRating.POSITIVE }        val negative = entries.count { it.rating == FeedbackRating.NEGATIVE }        val explicit = entries.count { it.type == FeedbackType.EXPLICIT }        val implicit = entries.count { it.type == FeedbackType.IMPLICIT }        val corrections = entries.count { it.type == FeedbackType.CORRECTION }        return FeedbackStats(            totalEntries = total,            positiveCount = positive,            negativeCount = negative,            explicitCount = explicit,            implicitCount = implicit,            correctionCount = corrections,            satisfactionRate = if (total > 0) positive.toFloat() / total else 0f,        )    }    /**     * Delete feedback for a specific request (user-initiated).     */    fun deleteForRequest(correlationId: CorrelationId): Int {        val before = entries.size        entries.removeIf { it.correlationId == correlationId }        val removed = before - entries.size        if (removed > 0) {            Timber.tag("NOUS.Feedback").i("Deleted %d feedback entries for %s", removed, correlationId.value.take(8))        }        return removed    }    /**     * Delete all feedback older than [maxAgeDays].     */    fun cleanupOldEntries(maxAgeDays: Long = 90): Int {        val cutoff = Instant.now().minusSeconds(maxAgeDays * 24 * 60 * 60)        val before = entries.size        entries.removeIf { it.timestamp.isBefore(cutoff) }        val removed = before - entries.size        if (removed > 0) {            Timber.tag("NOUS.Feedback").i("Cleaned up %d old feedback entries", removed)        }        return removed    }    /**     * Clear all feedback (Settings → Privacy → Clear All).     */    fun clear() {        entries.clear()    }    // ─── Internal ────────────────────────────────────────────────────────    private fun recordImplicit(        correlationId: CorrelationId,        rating: FeedbackRating,        comment: String,    ) {        val entry = FeedbackEntry(            correlationId = correlationId,            type = FeedbackType.IMPLICIT,            rating = rating,            comment = comment,            timestamp = Instant.now(),        )        addEntry(entry)        Timber.tag("NOUS.Feedback").v("Implicit feedback: %s for %s", rating, correlationId.value.take(8))    }    private fun addEntry(entry: FeedbackEntry) {        entries.add(entry)        // Trim if over capacity (remove oldest)        while (entries.size > maxEntries) {            entries.poll()        }    }    companion object {        /** Patterns indicating positive feedback (case-insensitive). */        val POSITIVE_PATTERNS: List<Regex> = listOf(            Regex("\\bthank\\s+you\\b"),            Regex("\\bthanks\\b"),            Regex("\\bperfect\\b"),            Regex("\\bthat'?s\\s+right\\b"),            Regex("\\bcorrect\\b"),            Regex("\\bgood\\s+job\\b"),            Regex("\\bwell\\s+done\\b"),            Regex("\\bawesome\\b"),            Regex("\\bgreat\\b"),            Regex("\\bexactly\\b"),            Regex("\\byes\\s*,?\\s*that'?s\\s+it\\b"),        )        /** Patterns indicating negative feedback (case-insensitive). */        val NEGATIVE_PATTERNS: List<Regex> = listOf(            Regex("\\bno\\s*,?\\s*that'?s\\s+wrong\\b"),            Regex("\\bwrong\\b"),            Regex("\\bnot\\s+right\\b"),            Regex("\\bthat'?s\\s+not\\s+what\\s+i\\s+asked\\b"),            Regex("\\btry\\s+again\\b"),            Regex("\\bstupid\\b"),            Regex("\\buseless\\b"),            Regex("\\bi\\s+meant\\b"),            Regex("\\bactually\\b"),  // often precedes a correction        )    }}/** * A single feedback entry. */data class FeedbackEntry(    /** Which request this feedback is for. */    val correlationId: CorrelationId,    /** Type of feedback. */    val type: FeedbackType,    /** Positive or negative. */    val rating: FeedbackRating,    /** Optional comment (user-typed or detected pattern). */    val comment: String?,    /** When the feedback was recorded. */    val timestamp: Instant,)/** * Type of feedback. */enum class FeedbackType {    /** User explicitly tapped thumbs up/down. */    EXPLICIT,    /** Detected from user's next message (e.g., "thank you"). */    IMPLICIT,    /** User provided the correct answer after a failure. */    CORRECTION,}/** * Feedback rating. */enum class FeedbackRating {    POSITIVE,    NEGATIVE,}/** * Aggregate feedback stats. */data class FeedbackStats(    val totalEntries: Int,    val positiveCount: Int,    val negativeCount: Int,    val explicitCount: Int,    val implicitCount: Int,    val correctionCount: Int,    val satisfactionRate: Float,)